const KERALA_MURAL_INFO={title:"Kerala Mural Painting",region:"Kerala",state:"Kerala, India",tradition:"Temple wall painting",era:"9th century CE – present",practitioners:"Traditional temple artisans (Acharyas) and modern mural artists",giStatus:"Documented heritage tradition",summary:"Kerala mural painting is a sacred temple art form that flourished from the 9th to the 12th centuries CE. Drawn on the lime-plastered walls of temples and palaces, the murals depict Hindu epics, gods, and goddesses in a distinctive stylised form with bold outlines, flat colours, and a strict palette of five natural pigments (Panchavarna)."},HISTORICAL_BACKGROUND=[{heading:"Origins in the Bhakti Movement",body:"Kerala mural painting traces its origins to the Bhakti movement that swept through South India between the 8th and 10th centuries CE. The movement emphasised personal devotion to Vishnu and Shiva, and temples became the focal point of community life. The walls of these temples — freshly plastered with lime and sand — became the canvas for narrative depictions of the gods' lives and deeds."},{heading:"The Golden Age (9th–12th Century)",body:"The golden age of Kerala murals was the 9th to 12th century, when the Chera, Ay, and Mushika dynasties patronised temple construction across the Malabar coast. The earliest surviving murals are at the Thirunandikkara Cave Temple (9th century) and the Pundarikapuram Vishnu Temple. Over 500 temple sites with murals have been documented in Kerala, making it one of the densest mural regions in India."},{heading:"The Panchavarna Palette",body:"Kerala murals use a strict five-colour palette called Panchavarna: red (Sindhoora), yellow (Manjal), green (Ilappullu), black (Kari), and white (Safed). Each pigment is derived from natural minerals, roots, or soot, and each colour carries symbolic meaning — red for passion and power, yellow for knowledge and austerity, green for life and nature, black for transcendence, and white for purity."},{heading:"Stylistic Features",body:"Kerala murals are instantly recognisable by their bold, dark outlines; flat, unshaded colour fields; exaggerated eye and hand gestures; and a distinctive forward-bending posture for female figures. The figures are stylised rather than naturalistic, with bodies in complex twisting poses derived from the Natyashastra — the ancient Sanskrit treatise on dance and dramaturgy. The backgrounds are typically flat red or yellow, with no atmospheric perspective."},{heading:"Decline and Revival",body:"The mural tradition declined after the 16th century as temple patronage waned and the Portuguese and Dutch introduced oil painting to the Malabar coast. The murals were neglected for centuries, and many were lost to weather, white-washing, and reconstruction. A revival began in the mid-20th century, led by artist Mammiyoor Krishnankutty Nair and the Guruvayur Devasthanam. Today, the tradition is kept alive by trained mural artists who work on both temple commissions and modern canvas adaptations."}],NATURAL_PIGMENTS=[{name:"Sindhoora (Red)",color:"#c0392b",description:"Red ochre or cinnabar. Represents Rajas guna — passion, power, and the active principle. Used for the bodies of male deities and the backgrounds of battle scenes.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Red_ochre.jpg/200px-Red_ochre.jpg"},{name:"Manjal (Yellow)",color:"#d4a017",description:"Yellow ochre or turmeric. Represents Sattva guna — purity, knowledge, and truth. Used for the bodies of female deities, halos, and sacred objects.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"},{name:"Ilappullu (Green)",color:"#27ae60",description:"Green from the leaves of Neelakkoduveli (Justicia simplex) or other local plants. Represents life, nature, and the pacific principle. Used for the bodies of Vishnu and his avatars.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"},{name:"Kari (Black)",color:"#1a1a1a",description:"Soot from burning coconut shells or resin. Represents Tamas guna — transcendence and the void. Used for outlines, hair, and the bodies of dark-skinned deities like Krishna.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"},{name:"Safed (White)",color:"#f8f0e0",description:"Lime or chalk powder. Represents purity and spiritual illumination. Used for highlights, ornaments, and the sacred thread (Yajnopavita).",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"}],TEMPLE_MURALS=[{name:"Mattancherry Palace Murals",location:"Kochi",era:"16th–17th century",description:"The most extensive collection of Kerala murals in a single site. The palace's walls and ceilings depict scenes from the Ramayana, Mahabharata, and the Krishna Lila in vivid reds, yellows, and greens.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Mattancherry_Palace_Mural.jpg/440px-Mattancherry_Palace_Mural.jpg"},{name:"Guruvayur Temple",location:"Thrissur",era:"16th century (restored)",description:"The temple's walls feature murals of Krishna's life, drawn in the distinctive Guruvayur style with bold outlines and flat colour fields. A major pilgrimage site and a living centre of the mural revival.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Guruvayur_Temple_Mural.jpg/440px-Guruvayur_Temple_Mural.jpg"},{name:"Thirunandikkara Cave Temple",location:"Kanyakumari (historical Kerala)",era:"9th century",description:"The oldest surviving Kerala murals, carved into a rock-cut cave temple. The faded traces show the early stylistic roots of the tradition, including the use of red and yellow ochres.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Thirunandikkara_Cave.jpg/440px-Thirunandikkara_Cave.jpg"},{name:"Pundarikapuram Vishnu Temple",location:"Kottayam",era:"12th–13th century",description:"Features exceptionally well-preserved murals of Vishnu in his various avatars, including a striking depiction of Narasimha (the man-lion avatar) tearing the demon Hiranyakashipu.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Pundarikapuram_Mural.jpg/440px-Pundarikapuram_Mural.jpg"},{name:"Ettumanoor Mahadeva Temple",location:"Kottayam",era:"16th century",description:"The temple's walls depict the dance of Shiva (Nataraja) in a mural widely regarded as the finest single Kerala mural composition. The 'Pradosha Nritha' panel is a masterpiece of stylised movement.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Ettumanoor_Shiva_Mural.jpg/440px-Ettumanoor_Shiva_Mural.jpg"},{name:"Thodeekalam Siva Temple",location:"Kannur",era:"15th–16th century",description:"Features extensive murals of the Shiva Purana, including the marriage of Shiva and Parvati. The figures are unusually large for Kerala murals and show refined shading.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Thodeekalam_Mural.jpg/440px-Thodeekalam_Mural.jpg"}],GALLERY_ITEMS=[{title:"Shiva as Nataraja (Ettumanoor)",region:"Ettumanoor, Kottayam",year:"16th century",description:"The 'Pradosha Nritha' panel from the Ettumanoor temple — Shiva in his cosmic dance, with Parvati watching. Widely regarded as the finest single Kerala mural composition.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Ettumanoor_Shiva_Mural.jpg/440px-Ettumanoor_Shiva_Mural.jpg",category:"shiva"},{title:"Krishna Lila (Mattancherry)",region:"Mattancherry Palace, Kochi",year:"16th–17th century",description:"A scene from the Krishna Lila at Mattancherry Palace, showing the young Krishna stealing butter. The flat red background and bold outlines are characteristic of the mature Kerala style.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Mattancherry_Palace_Mural.jpg/440px-Mattancherry_Palace_Mural.jpg",category:"vishnu"},{title:"Goddess Bhagavathi",region:"Pundarikapuram, Kottayam",year:"12th–13th century",description:"A depiction of the goddess Bhagavathi (Durga) in her fierce form, with multiple arms and a garland of skulls. The green skin tone represents her connection to nature.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Pundarikapuram_Mural.jpg/440px-Pundarikapuram_Mural.jpg",category:"goddess"},{title:"Ramayana Scene (Mattancherry)",region:"Mattancherry Palace, Kochi",year:"16th–17th century",description:"A battle scene from the Ramayana at Mattancherry. The warriors are drawn in the distinctive forward-lunge posture, with elaborate headgear and weapons.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Guruvayur_Temple_Mural.jpg/440px-Guruvayur_Temple_Mural.jpg",category:"epic"},{title:"Vishnu on Garuda",region:"Thodeekalam, Kannur",year:"15th–16th century",description:"Vishnu mounted on his vahana (vehicle) Garuda, the eagle. The detailed plumage of Garuda and the elaborate crown of Vishnu show the refinement of the late Kerala mural style.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Thodeekalam_Mural.jpg/440px-Thodeekalam_Mural.jpg",category:"vishnu"},{title:"Narasimha Avatar",region:"Pundarikapuram, Kottayam",year:"12th–13th century",description:"The man-lion avatar of Vishnu, Narasimha, tearing the demon Hiranyakashipu. The fierce expression and the red background create an intense, dramatic composition.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Thirunandikkara_Cave.jpg/440px-Thirunandikkara_Cave.jpg",category:"vishnu"}],GALLERY_CATEGORIES=[{id:"all",label:"All"},{id:"shiva",label:"Shiva"},{id:"vishnu",label:"Vishnu"},{id:"goddess",label:"Goddess"},{id:"epic",label:"Epics"}],REFERENCES_LIST=[{title:"Kerala Murals — A Comprehensive Study",author:"Suresh, M. V.",publisher:"Kerala Bhasha Institute",year:2008,url:"https://en.wikipedia.org/wiki/Mural_painting#Kerala_murals"},{title:"The Murals of Kerala",author:"Raghava Varier, M. R.",publisher:"State Department of Archaeology, Kerala",year:1995,url:"https://en.wikipedia.org/wiki/Kerala_mural_painting"},{title:"Mattancherry Palace — A Heritage Guide",author:"Archaeological Survey of India",publisher:"ASI",year:2012,url:"https://en.wikipedia.org/wiki/Mattancherry_Palace"},{title:"Kerala Temple Art — Documentation",author:"Centre for Cultural Resources and Training (CCRT)",publisher:"Ministry of Culture, Government of India",year:2018,url:"https://ccrtindia.gov.in/"},{title:"Wikipedia: Kerala mural painting",author:"Wikipedia contributors",publisher:"Wikipedia",year:2024,url:"https://en.wikipedia.org/wiki/Kerala_mural_painting"},{title:"Mural Paintings of India — A Bibliography",author:"National Museum, New Delhi",publisher:"National Museum Institute",year:2011,url:"https://nationalmuseumindia.gov.in/"}];"undefined"!=typeof window&&(window.KERALA_DATA={info:KERALA_MURAL_INFO,history:HISTORICAL_BACKGROUND,pigments:NATURAL_PIGMENTS,temples:TEMPLE_MURALS,gallery:GALLERY_ITEMS,galleryCategories:GALLERY_CATEGORIES,references:REFERENCES_LIST}),"undefined"!=typeof module&&module.exports&&(module.exports={KERALA_MURAL_INFO:KERALA_MURAL_INFO,HISTORICAL_BACKGROUND:HISTORICAL_BACKGROUND,NATURAL_PIGMENTS:NATURAL_PIGMENTS,TEMPLE_MURALS:TEMPLE_MURALS,GALLERY_ITEMS:GALLERY_ITEMS,GALLERY_CATEGORIES:GALLERY_CATEGORIES,REFERENCES_LIST:REFERENCES_LIST});